using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TrafficWorldTests
{
 static void Go(WorldSession s,string dest){Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:trip/"+s.DiagnosticSnapshot().Requests.Length,dest),s.Revision).Code);s.AdvanceTo(s.Seconds+1);}
 static void Arrive(WorldSession s){for(int g=0;TravelWorld.Active(s.DiagnosticSnapshot())&&g<32;g++)s.AdvanceTo(s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[^1].EndAt);}
 static JourneyLeg Sea(WorldSession s)=>s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs.First(l=>NationalRoutes.Sea(l.Edge));
 static void Decide(WorldSession s,string? dest){Assert.Equal(ResultCode.Accepted,s.ChangeTravel(TravelControl.Request(s.DiagnosticSnapshot(),"request:decision/"+s.DiagnosticSnapshot().TravelDecisions!.Length,dest),s.Revision).Code);}
 static void Inspect(WorldSession s){var w=s.DiagnosticSnapshot();var node=TravelWorld.Origin(w,w.PlayerControl);foreach(var e in BranchRoutes.GraphEdges(w).Where(e=>e.From==node||e.To==node))Assert.Equal(ResultCode.Accepted,s.InspectRoad(w.PlayerControl,e.Id,s.Revision).Code);}
 static (long Start,long Departure,JourneyLeg Leg) SeaTimes(){var s=new WorldSession(TrafficWorld.Create());Go(s,"sumoto");var l=Sea(s);return(l.StartAt,TravelWorld.Departure(s.DiagnosticSnapshot(),l.Edge,l.StartAt),l);}
 static WorldSession Port(long offset=0){var t=SeaTimes();var s=new WorldSession(TrafficWorld.Create([new(t.Departure+offset,t.Leg.Edge,true),new(t.Departure+600,t.Leg.Edge,false)]));Go(s,"sumoto");return s;}
 [Theory][InlineData(-1)][InlineData(0)] public void OutageBeforeOrAtDepartureStopsAtPort(long offset){var t=SeaTimes();var s=Port(offset);s.AdvanceTo(t.Departure+offset);Assert.Equal(ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks.Single().Execution);Assert.Equal(RegionalCampaign.Site(t.Leg.From),s.GetActorView(ContractFixture.Officer).Location.Site);Assert.False(s.GetBranchView(ContractFixture.Officer).Walking);Assert.Single(s.DiagnosticSnapshot().TrafficStops!);var p=s.GetBranchView(ContractFixture.Officer).Position;s.AdvanceTo(t.Departure+601);Assert.Equal(p,s.GetBranchView(ContractFixture.Officer).Position);}
 [Fact] public void OutageAfterDepartureDoesNotStopAnAfloatActor(){var t=SeaTimes();var s=Port(1);s.AdvanceTo(t.Departure+100);Assert.True(s.GetBranchView(ContractFixture.Officer).Walking);Assert.Empty(s.DiagnosticSnapshot().TrafficStops!);Arrive(s);Assert.Equal(new EntityId("site:sumoto"),s.GetActorView(ContractFixture.Officer).Location.Site);}
 [Fact] public void PortCancellationBeforeOutageIsNotAppliedTwice(){var t=SeaTimes();var s=Port();s.AdvanceTo(t.Departure-1);Decide(s,null);s.AdvanceTo(t.Departure);Assert.Empty(s.DiagnosticSnapshot().TrafficStops!);Assert.Single(s.DiagnosticSnapshot().TravelDecisions!);Assert.Equal("port-cancelled",s.DiagnosticSnapshot().TravelDecisions!.Single().Result);}
 [Fact] public void LocalReopeningMustBeObservedBeforeExplicitRestart(){var t=SeaTimes();var s=Port();s.AdvanceTo(t.Departure);s.AdvanceTo(t.Departure+600);Assert.Contains(t.Leg.Edge,BranchRoutes.KnownBlocked(s.DiagnosticSnapshot(),ContractFixture.Officer));Inspect(s);Assert.DoesNotContain(t.Leg.Edge,BranchRoutes.KnownBlocked(s.DiagnosticSnapshot(),ContractFixture.Officer));var start=s.Seconds;Go(s,"sumoto");var leg=s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs.First();Assert.True(TravelWorld.Departure(s.DiagnosticSnapshot(),leg.Edge,leg.StartAt)>=start+300);Arrive(s);Assert.Equal(new EntityId("site:sumoto"),s.GetActorView(ContractFixture.Officer).Location.Site);}
 [Fact] public void RemoteOutageCannotLeakIntoPlanOrPositionBeforeLocalContact(){var t=SeaTimes();var a=new WorldSession(TrafficWorld.Create());var b=Port();Go(a,"sumoto");a.AdvanceTo(100);b.AdvanceTo(100);Assert.Equal(ContractJson.Write(a.GetBranchView(ContractFixture.Officer)),ContractJson.Write(b.GetBranchView(ContractFixture.Officer)));Assert.Equal(ContractJson.Write(a.GetCourierView(ContractFixture.Lord)),ContractJson.Write(b.GetCourierView(ContractFixture.Lord)));}
 static (WorldSession Session,long At,string Node) Redirect(bool blockAll){var baseline=new WorldSession(TrafficWorld.Create());Go(baseline,"sakai");baseline.AdvanceTo(100);var req=TravelControl.Request(baseline.DiagnosticSnapshot(),"request:setup","edo");var d=TravelControl.Prepare(baseline.DiagnosticSnapshot(),req);var affected=blockAll?BranchRoutes.GraphEdges(baseline.DiagnosticSnapshot()).Where(e=>e.From==d.Node||e.To==d.Node).Select(e=>e.Id).ToArray():[d.After[d.Before.TakeWhile(l=>l.EndAt<=d.EffectiveAt).Count()].Edge];var cs=affected.SelectMany(id=>new[]{new RoadCondition(d.EffectiveAt,id,true),new RoadCondition(d.EffectiveAt+600,id,false)}).ToArray();var s=new WorldSession(TrafficWorld.Create(cs));Go(s,"sakai");s.AdvanceTo(100);Decide(s,"edo");return(s,d.EffectiveAt,d.Node);}
 [Fact] public void SameTimeRedirectAndRoadClosureUseLocalDetour(){var(s,at,node)=Redirect(false);s.AdvanceTo(at);Assert.Equal("redirected",s.DiagnosticSnapshot().TravelDecisions!.Single().Result);Assert.Empty(s.DiagnosticSnapshot().TrafficStops!);Assert.NotEmpty(BranchRoutes.KnownBlocked(s.DiagnosticSnapshot(),ContractFixture.Officer));Arrive(s);Assert.Equal(new EntityId("site:edo"),s.GetActorView(ContractFixture.Officer).Location.Site);}
 [Fact] public void NoDetourStopsAtTheActualNodeAndDoesNotUndoTheDecision(){var(s,at,node)=Redirect(true);s.AdvanceTo(at);Assert.Equal(RegionalCampaign.Site(node),s.GetActorView(ContractFixture.Officer).Location.Site);Assert.Equal("redirected",s.DiagnosticSnapshot().TravelDecisions!.Single().Result);Assert.Equal("road-unavailable",s.DiagnosticSnapshot().TrafficStops!.Single().Reason);s.AdvanceTo(at+600);Inspect(s);Go(s,"edo");Assert.Equal(node,s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[0].From);Arrive(s);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)] public void SavedCollisionStagesRestoreAndContinueExactly(int phase){var t=SeaTimes();WorldSession s;long final;if(phase<2){var setup=Redirect(true);s=setup.Session;s.AdvanceTo(phase==0?setup.At-1:setup.At);final=setup.At+600;}else{s=Port();s.AdvanceTo(phase==2?t.Departure-1:t.Departure);final=t.Departure+600;}var root=Path.Combine(Path.GetTempPath(),"traffic-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,TrafficWorld.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.375,1));var host=new WorldSessionHost(new(TrafficWorld.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("test"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetBranchView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetBranchView(ContractFixture.Officer)));host.Current.SetPaused(false);s.AdvanceTo(final);host.Current.AdvanceTo(final);Inspect(s);Inspect(host.Current);Go(s,phase<2?"edo":"sumoto");Go(host.Current,phase<2?"edo":"sumoto");Arrive(s);Arrive(host.Current);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Branches),ContractJson.Write(host.Current.DiagnosticSnapshot().Branches));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().TrafficStops),ContractJson.Write(host.Current.DiagnosticSnapshot().TrafficStops));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Couriers),ContractJson.Write(host.Current.DiagnosticSnapshot().Couriers));Assert.Equal(s.GetBranchView(ContractFixture.Officer).Position,host.Current.GetBranchView(ContractFixture.Officer).Position);}
 [Fact] public void PortStopMustHaveActualClosureAndLocalSighting(){var t=SeaTimes();var s=Port();s.AdvanceTo(t.Departure);var w=s.DiagnosticSnapshot();w.Couriers=w.Couriers! with{Sightings=[]};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));w=s.DiagnosticSnapshot();w.TrafficStops=null;Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
 [Fact] public void OldControlSaveRequiresExplicitMigration(){var root=Path.Combine(Path.GetTempPath(),"traffic-old-"+Guid.NewGuid().ToString("N"));var s=new WorldSession(TravelControl.Create());new GenerationSaveStore(root,TravelControl.Create().Definitions).Save(s,"old",s.DiagnosticSnapshot().WorldId,new(0,1));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,TrafficWorld.Create().Definitions).Prepare("old"));}
 [Theory][InlineData(0,true)][InlineData(1,false)] public void PhysicalCourierAlsoChecksServiceUntilDeparture(long offset,bool fails){var baseline=new WorldSession(TrafficWorld.Create());Go(baseline,"sumoto");Arrive(baseline);baseline.InspectRoad(ContractFixture.Officer,"nation-sakai-sumoto",baseline.Revision);var bc=baseline.DiagnosticSnapshot().Couriers!.Missions.Last();var bl=bc.Legs.First(l=>NationalRoutes.Sea(l.Edge));var dep=TravelWorld.Departure(baseline.DiagnosticSnapshot(),bl.Edge,bl.StartAt);var s=new WorldSession(TrafficWorld.Create([new(dep+offset,bl.Edge,true),new(dep+600,bl.Edge,false)]));Go(s,"sumoto");Arrive(s);s.InspectRoad(ContractFixture.Officer,"nation-sakai-sumoto",s.Revision);var c=s.DiagnosticSnapshot().Couriers!.Missions.Last();s.AdvanceTo(dep+offset);Assert.Equal(fails,s.DiagnosticSnapshot().Couriers!.Missions.Single(x=>x.Attempt==c.Attempt).Obstructed);if(fails){s.AdvanceTo(dep+3);Assert.True(HakutaiKagami.Core.Messaging.MessageFlow.FailureKnown(s.DiagnosticSnapshot().Messaging,c.Attempt,ContractFixture.Officer.Value));Assert.False(HakutaiKagami.Core.Messaging.MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,s.DiagnosticSnapshot().Messaging.Attempts.Single(a=>a.Id==c.Attempt).MessageId,ContractFixture.Lord.Value));}else{s.AdvanceTo(c.ReadyAt);Assert.Contains(s.GetCourierView(ContractFixture.Lord),v=>v.Status=="受領済");}}
 [Fact] public void ClosureOfTheRoadAlreadyBeingTraversedDoesNotTeleportOrTurnBack(){var baseline=new WorldSession(TrafficWorld.Create());Go(baseline,"sakai");var leg=baseline.DiagnosticSnapshot().Branches!.Journeys.Single().Legs[0];var s=new WorldSession(TrafficWorld.Create([new(10,leg.Edge,true)]));Go(s,"sakai");s.AdvanceTo(100);Assert.True(s.GetBranchView(ContractFixture.Officer).Walking);Assert.Empty(s.DiagnosticSnapshot().TrafficStops!);Assert.Empty(BranchRoutes.KnownBlocked(s.DiagnosticSnapshot(),ContractFixture.Officer));s.AdvanceTo(leg.EndAt);Assert.Equal(leg, s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs[0]);}
}
